import{_ as t,o as e,c as d,a2 as n}from"./chunks/framework.DtFGJNng.js";const k=JSON.parse('{"title":"Skill dan CLI","description":"","frontmatter":{},"headers":[],"relativePath":"skill-dan-cli.md","filePath":"skill-dan-cli.md","lastUpdated":1794463556000}'),i={name:"skill-dan-cli.md"};function o(s,a,r,l,c,u){return e(),d("div",null,[...a[0]||(a[0]=[n(`<h1 id="skill-dan-cli" tabindex="-1">Skill dan CLI <a class="header-anchor" href="#skill-dan-cli" aria-label="Permalink to &quot;Skill dan CLI&quot;">​</a></h1><p>deuz punya dua bagian, dan tempat memakainya berbeda:</p><table tabindex="0"><thead><tr><th></th><th>Diketik di</th><th>Contoh</th><th>Fungsi</th></tr></thead><tbody><tr><td><strong>Skill</strong></td><td>Chat AI agent (Claude Code)</td><td><code>/deuz:continue specs</code></td><td>Pekerjaan yang butuh penilaian: menulis dokumen, membaca kode, mengerjakan task</td></tr><tr><td><strong>CLI</strong></td><td>Terminal (dan dipanggil skill di belakang layar)</td><td><code>deuz status</code></td><td>Aturan yang harus pasti: status, kunci, konfirmasi, validasi, archive</td></tr></tbody></table><p>Sehari-hari, kamu cukup memakai skill. Skill memanggil CLI dengan <code>--json</code> lalu menyajikan hasilnya. CLI dipakai langsung kalau ingin mengecek cepat, menjalankan di CI, atau bekerja tanpa agent.</p><p>Kalau CLI tidak ditemukan, skill menjalankan aturan di <code>core/RULES.md</code> sendiri <strong>dan memberi tahu bahwa hasilnya dihitung agent</strong>. Hasil CLI lebih bisa dipercaya, jadi pastikan <code>bin/deuz</code> sudah di-build.</p><h2 id="skill" tabindex="-1">Skill <a class="header-anchor" href="#skill" aria-label="Permalink to &quot;Skill&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>Kapan dipakai</th></tr></thead><tbody><tr><td><code>/deuz:init</code></td><td>Sekali per proyek: membuat <code>deuz/config.yaml</code> (peran, homes, bahasa, context)</td></tr><tr><td><code>/deuz:new &lt;nama&gt;</code></td><td>Memulai work baru. Agent menanyakan tujuan, jenis work, dan hasil triage</td></tr><tr><td><code>/deuz:status [nama]</code></td><td>Melihat status tiap dokumen, apa yang terkunci, dan siapa yang ditunggu</td></tr><tr><td><code>/deuz:continue [artifact]</code></td><td>Menulis atau melanjutkan <strong>satu</strong> dokumen dari template dan instruksinya</td></tr><tr><td><code>/deuz:ready &lt;artifact&gt; --as &lt;peran&gt;[,&lt;peran&gt;]</code></td><td>Mencatat konfirmasi pemilik. Untuk <code>--as business</code>, jalankan setelah rapat</td></tr><tr><td><code>/deuz:apply &lt;tasks&gt;</code></td><td>Mengerjakan daftar task dan mencentang task yang terbukti selesai</td></tr><tr><td><code>/deuz:archive [nama]</code></td><td>Menggabungkan delta ke spec permanen dan memindahkan work ke archive</td></tr><tr><td><code>/deuz:baseline &lt;capability&gt;</code></td><td>Menulis spec permanen untuk perilaku yang sudah ada di kode</td></tr></tbody></table><h2 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to &quot;CLI&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>deuz [--root DIR] &lt;command&gt; [arguments] [--json]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  init --role id=Name... --home name=path|null... [--language id] [--schema default]</span></span>
<span class="line"><span>  new &lt;work&gt; [--date YYYY-MM-DD]</span></span>
<span class="line"><span>  status [work] [--write]</span></span>
<span class="line"><span>  instructions &lt;artifact&gt; [--work work]</span></span>
<span class="line"><span>  ready &lt;artifact&gt; --as role[,role] [--work work]</span></span>
<span class="line"><span>  validate [work]</span></span>
<span class="line"><span>  archive [work] [--dry-run] [--date YYYY-MM-DD] [--confirm-promote artifact]</span></span>
<span class="line"><span>  version</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Perintah</th><th>Menulis file?</th><th>Keterangan</th></tr></thead><tbody><tr><td><code>init</code></td><td>Ya</td><td>Membuat <code>deuz/config.yaml</code>. Gagal kalau file sudah ada</td></tr><tr><td><code>new</code></td><td>Ya</td><td>Membuat <code>deuz/work/&lt;nama&gt;/.deuz.yaml</code>. Nama harus kebab-case</td></tr><tr><td><code>status</code></td><td>Tidak</td><td>Status, siapa yang ditunggu, progres task, langkah berikutnya</td></tr><tr><td><code>status --write</code></td><td>Ya</td><td>Menulis ulang <code>.deuz.yaml</code> dari kondisi sekarang tanpa mengubah konfirmasi. Dipakai untuk migrasi work lama atau setelah konflik merge</td></tr><tr><td><code>instructions</code></td><td>Tidak</td><td>Bahan untuk agent menulis satu dokumen: template, instruksi, context, dokumen yang dibutuhkan</td></tr><tr><td><code>ready</code></td><td>Ya</td><td>Mencatat konfirmasi. Ditolak tanpa menulis apa pun kalau ada aturan yang dilanggar</td></tr><tr><td><code>validate</code></td><td>Tidak</td><td>Memeriksa format dokumen, spec, coverage map, dan aturan gate</td></tr><tr><td><code>archive</code></td><td>Ya</td><td>Menggabungkan delta, promote, lalu memindahkan work. <code>--dry-run</code> untuk melihat rencananya dulu</td></tr></tbody></table><p>Kode keluar: <code>0</code> berhasil, <code>1</code> ditolak oleh aturan, <code>2</code> salah pakai. Tanpa nama work, perintah memilih satu-satunya work aktif. Kalau ada beberapa, sebutkan namanya atau pakai <code>--work</code>.</p><p>CLI mencari <code>deuz/config.yaml</code> dari folder saat ini ke atas. <code>--root</code> menunjuk root proyek secara langsung.</p><h2 id="siapa-menjalankan-apa" tabindex="-1">Siapa menjalankan apa <a class="header-anchor" href="#siapa-menjalankan-apa" aria-label="Permalink to &quot;Siapa menjalankan apa&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Peran</th><th>Skill yang paling sering dipakai</th></tr></thead><tbody><tr><td>Analyst</td><td><code>new</code>, <code>continue</code> (proposal, specs), <code>ready --as analyst</code>, <code>ready --as business</code> setelah rapat, <code>baseline</code></td></tr><tr><td>Designer</td><td><code>continue ui-design</code>, <code>ready --as designer</code></td></tr><tr><td>Backend / frontend</td><td><code>continue api-contract</code>, <code>continue tasks-*</code>, <code>ready</code>, <code>apply</code></td></tr><tr><td>QA</td><td><code>continue tasks-test</code>, <code>ready --as qa</code>, <code>apply tasks-test</code></td></tr><tr><td>Siapa saja</td><td><code>status</code>, <code>archive</code></td></tr></tbody></table><h2 id="di-ci" tabindex="-1">Di CI <a class="header-anchor" href="#di-ci" aria-label="Permalink to &quot;Di CI&quot;">​</a></h2><p><code>deuz validate</code> cocok dijalankan di pipeline. Kode keluar <code>1</code> berarti ada error, misalnya format spec salah, scenario yang belum dipetakan di coverage map, atau proposal yang melanggar aturan gate. Proposal yang sudah <code>ready</code> tidak dievaluasi ulang, jadi mengaktifkan aturan baru tidak membuat work lama gagal.</p>`,16)])])}const m=t(i,[["render",o]]);export{k as __pageData,m as default};
